import {actions} from './actions.js';
import {dayKey} from './store.js';
import {muscleRegions,muscleNames} from './muscle-data.js';
import {muscleSummary,muscleMap,exerciseProgress,muscleAnswer} from './muscle.js';
import {equipmentAllows} from './training.js';
export function createMuscleUI(ctx){const d=ctx.data,e=ctx.esc;
 const entry=()=>`<article class="card muscle-entry"><div><span class="eyebrow">BODY MODULE // MUSCLE MAP</span><h2>What can your body do?</h2><p class="muted">Control. Capacity. Repeatable proof. Watch your configured paths develop across every region.</p></div><div class="actions"><button class="white" data-action="muscleMap">Open Muscle Map ↗</button><button data-action="muscleBalance">Training balance</button></div></article>`;
 function page(){return ctx.heading('Your capability map.','Every movement has its own story. Every tier needs real proof.',`<button data-action="muscleBalance">Training balance ↗</button>`)+`<div class="map-intro"><div class="map-orbit" aria-hidden="true">◇<span>BODY<br>MODULE</span></div><div><span class="eyebrow">STRENGTH // CONTROL // CONSISTENCY</span><h2>Build command, one path at a time.</h2><p>Percentages describe completed tiers in your configured primary paths. They do not measure muscle growth or physiological strength.</p></div></div>${Object.entries(muscleRegions).map(([region,names])=>`<section class="map-region"><div class="card-head"><h2>${region}</h2><span class="eyebrow">${names.length} CAPABILITY AREAS</span></div><div class="muscle-grid">${names.map(name=>{const m=muscleSummary(name,d(),dayKey());return `<button class="muscle-tile" data-action="muscleDetail" data-muscle="${name}"><span class="tile-top"><strong>${name}</strong><span>${m.percent}%</span></span>${ctx.progress(m.percent,name+' configured path completion')}<span class="muted">${m.done} / ${m.total} primary tiers proved</span><span class="legend">${m.lastTrained?'Last trained '+m.lastTrained:'Exposure not yet logged'} · ${m.weeklySessions} sessions / 7 days</span><span class="tile-bottom">${m.next?e(m.next.exercise.name)+' · '+m.next.state.stage:'Review recorded capabilities'} ↗</span></button>`}).join('')}</div></section>`).join('')}`}
 function movementRow(p,config){const primary=p.paths.some(x=>config.primarySkillIds.includes(x.skill.id)),controlled=p.current;return `<div class="row"><div class="row-main"><h3>${e(p.exercise.name)} <span class="pill">${primary?'PRIMARY':'OPTIONAL'}</span></h3><p>${controlled?p.exercise.resistance==='bodyweight'?controlled.reps+' controlled reps · '+controlled.seconds+' s':controlled.value+' '+e(controlled.unit)+' · '+controlled.reps+' reps':'No controlled load logged'}</p>${p.paths.map(x=>`<small>${e(x.level.name)} · ${x.state.stage} · ${x.state.percent}% current proof · ${x.dominated.length} path tiers dominated</small>`).join('')}<p class="legend">${p.records.length} exercise-specific PRs</p></div><button data-action="muscleExercise" data-exercise="${p.exercise.id}">View progress ↗</button></div>`}
 function detail(name){const m=muscleSummary(name,d(),dayKey());ctx.modal(e(name)+' / capability',`<div class="metrics"><div class="metric"><strong>${m.percent}%</strong><small>Configured primary tiers</small></div><div class="metric"><strong>${m.weeklySessions}</strong><small>Sessions in 7 days</small></div></div>${ctx.progress(m.percent)}<p class="legend">${m.done}/${m.total} tiers. Last trained: ${m.lastTrained||'not recorded'}. ${m.readiness.score===null?'Readiness is unknown.':'Readiness estimate '+m.readiness.score+'%.'} Primary paths define coverage; optional variations add breadth.</p><div class="actions"><button data-action="muscleConfig" data-muscle="${name}">Configure primary paths</button><button data-action="extraMuscle" data-muscle="${name}">Extra ${name} session</button></div><h3>Muscle milestones</h3>${m.milestones.map(x=>`<p>${x.complete?'✓':'○'} ${e(x.name)} · ${x.movements} distinct primary paths with ${x.tiersPerMovement} dominated tier${x.tiersPerMovement===1?'':'s'} each</p>`).join('')}${m.milestones.length?'':'<p class="legend">Choose at least two relevant primary paths to configure breadth milestones.</p>'}<p class="legend">A tier includes controlled technique, endurance, and configured qualifying practice days. One strong variation cannot prove every movement.</p>${m.next?`<div class="notice">Closest trial: ${e(m.next.exercise.name)} / ${e(m.next.level.name)} · ${m.next.state.percent}% current proof.<br><button data-action="skillLevel" data-skill="${m.next.skill.id}" data-level="${m.next.level.id}">View next proof</button></div>`:''}<h3>Your exercise paths</h3>${m.movements.map(p=>movementRow(p,m.config)).join('')}<h3>Recent changes</h3>${d().recordEvents.filter(r=>m.movements.some(p=>p.exercise.id===r.exerciseId)).sort((a,b)=>b.at.localeCompare(a.at)).slice(0,5).map(r=>`<p>${e(d().exercises.find(x=>x.id===r.exerciseId)?.name)} · ${e(r.type)}: ${r.value} ${e(r.unit)} · ${r.date}</p>`).join('')||'<p class="muted">Record changes will appear after logged sets.</p>'}<details><summary>Readiness inputs</summary>${m.readiness.reasons.map(r=>`<p class="legend">${e(r)}</p>`).join('')}</details>`)}
 function exerciseDetail(id){const ex=d().exercises.find(x=>x.id===id),p=exerciseProgress(ex,d());const same=p.history.filter(l=>l.form&&!l.pain).slice(0,20).reverse();const inverse=ex.resistance==='assistance'||id==='assisted-pullup',weighted=ex.resistance!=='bodyweight';const unit=weighted?inverse?'lb assistance':'lb':ex.measurement==='duration'?'s':'reps';const values=same.map(l=>weighted?l.weight:ex.measurement==='duration'?l.durationSeconds||0:l.reps);const max=Math.max(1,...values);const points=values.map((v,i)=>`${20+i*260/Math.max(1,values.length-1)},${110-v/max*85}`).join(' ');ctx.modal(e(ex.name)+' / exercise progress',`<p class="muted">${e(ex.movementType)} · ${ex.targetMuscles.map(e).join(', ')} · ${e(ex.equipment.join(', ')||'bodyweight')}</p><p class="legend">${inverse?'Lower assistance is harder. Assistance is never ranked as lifted weight.':'Compare this exercise only; different movements and equipment are not equivalent.'}</p>${same.length?`<figure class="exercise-chart"><svg viewBox="0 0 300 130" role="img" aria-label="${e(ex.name)} recorded ${unit} over ${same.length} controlled sets"><path d="M20 20V110H280" stroke="#454950" fill="none"/><polyline points="${points}" fill="none" stroke="#f3f3f4" stroke-width="2"/>${values.map((v,i)=>`<circle cx="${20+i*260/Math.max(1,values.length-1)}" cy="${110-v/max*85}" r="3" fill="white"/>`).join('')}</svg><figcaption>${same[0].date} → ${same.at(-1).date} · ${unit} · recorded controlled sets</figcaption></figure>`:'<p class="empty">Log controlled sets to start your exercise trend.</p>'}<h3>Dominance paths</h3>${p.paths.map(x=>`<div class="row"><div class="row-main"><h3>${e(x.skill.name)}</h3><p>${e(x.level.name)} · ${x.state.stage} · ${x.state.percent}% current proof</p><p>${x.dominated.map(l=>e(l.name)).join(', ')||'No dominated tiers yet'}</p></div><button data-action="skillLevel" data-skill="${x.skill.id}" data-level="${x.level.id}">Work toward Dominance</button>${x.skill.ladder?`<button data-action="exerciseLadder" data-exercise="${id}">Configure load ladder</button>`:''}</div>`).join('')}<button data-action="freeExtra" data-exercise="${id}">Free session</button><h3>Personal records</h3>${p.records.map(r=>`<div class="row"><span>${e(r.type)} · ${r.value} ${e(r.unit)} · ${r.date}</span><button data-action="session" data-id="${r.sourceSession}">Source session</button></div>`).join('')||'<p class="muted">No PRs recorded.</p>'}<h3>Same-exercise history</h3>${p.history.slice(0,30).map(l=>`<div class="row"><div class="row-main"><p>${l.date} · ${l.reps} reps · ${l.weight} ${inverse?'lb assistance':'lb'} · ${l.durationSeconds||0} s · ${l.form?'controlled':'form unconfirmed'}${l.pain?' · pain / not proof':''}</p></div><button data-action="session" data-id="${l.sessionId}">Session</button></div>`).join('')||'<p class="empty">No recorded sets.</p>'}<h3>Related goals</h3>${d().goals.filter(g=>p.paths.some(x=>x.skill.levelDefinitions.some(l=>l.provesGoal===g.id))).map(g=>`<p>${e(g.name)}</p>`).join('')||'<p class="legend">This movement contributes capability proof without requiring a separate goal.</p>'}`)}
 function balance(){const list=muscleMap(d(),dayKey());ctx.modal('Training balance / recorded coverage',`<p class="legend">Compare exposure and configured path coverage, not biological strength. Missing records are unknown. Differences are not a medical diagnosis.</p>${list.map(m=>`<div class="row"><div class="row-main"><h3>${m.name}</h3><p>${m.percent}% configured tiers · ${m.weeklySessions} sessions / 7 days · ${m.lastTrained||'never logged'}</p>${ctx.progress(m.percent)}</div><button data-action="muscleDetail" data-muscle="${m.name}">View</button></div>`).join('')}`)}
 async function handleAction(b){const a=b.dataset.action,name=b.dataset.muscle,id=b.dataset.exercise;switch(a){case 'muscleMap':ctx.navigate('Muscle Map');break;case 'muscleDetail':detail(name);break;case 'muscleExercise':exerciseDetail(id);break;case 'muscleBalance':balance();break;case 'muscleConfig':{const m=muscleSummary(name,d(),dayKey());ctx.modal(e(name)+' / primary paths',`<form class="fields"><p>Choose the primary paths that define your coverage. Other relevant paths remain optional; saved proofs are preserved.</p>${[...m.config.primarySkillIds,...m.config.optionalSkillIds].map(id=>`<label><input style="width:auto" type="checkbox" name="path" value="${id}" ${m.config.primarySkillIds.includes(id)?'checked':''}> ${e(d().skillDefinitions.find(s=>s.id===id)?.name)}</label>`).join('')}<button class="white">Save primary paths</button></form>`,f=>actions.dispatch('saveMusclePaths',{muscle:name,primarySkillIds:f.getAll('path')}));break}case 'exerciseLadder':{const p=exerciseProgress(d().exercises.find(x=>x.id===id),d()).paths.find(x=>x.skill.ladder);ctx.modal(e(p.exercise?.name||d().exercises.find(x=>x.id===id).name)+' / load ladder',`<form class="fields"><p class="legend">${e(p.skill.ladder.direction)} · ${e(p.skill.ladder.unit)}. Existing practiced tiers keep their rules and order.</p>${ctx.field('Tier values · comma-separated','values','text',p.skill.ladder.values.join(', '),'required')}<button class="white">Save exercise ladder</button></form>`,f=>actions.dispatch('saveExerciseLadder',{exerciseId:id,ladder:{...p.skill.ladder,values:f.get('values').split(',').map(v=>Number(v.trim()))}}));break}default:return false}return true}
 function command(text){const q=text.toLowerCase().replaceAll('’',"'");if(!/muscle|triceps|tricep|biceps|bicep|shoulder|lats|arm progress|forearm|chest|delts|quads|hamstring|glutes|calves|hips|obliques/.test(q))return false;if(!ctx.pref().memory.training){ctx.modal('Caelum / memory controls','<p>Enable Training access to use exercise progress.</p>');return true}if(/arm progress/.test(q)){ctx.modal('Caelum / arm capability', ['Biceps','Triceps','Forearms'].map(n=>`<h3>${n}</h3><p class="caelum-reply">${e(muscleAnswer('How strong are my '+n,d(),dayKey()))}</p>`).join(''));return true}if(/extra|what.*train/.test(q)){const name=muscleNames.find(n=>q.includes(n.toLowerCase()))||'Triceps';if(!ctx.pref().memory.schedule){ctx.modal('Caelum / protected time','<p>Enable Schedule access for recommendations that respect protected commitments.</p><button data-action="extraArea">Choose a session manually</button>');return true}ctx.extraMuscle(name);return true}const normalized=q.replace(/tricep\b/g,'triceps').replace(/bicep\b/g,'biceps');const permitted={...d(),checkins:ctx.pref().memory.metrics?d().checkins:[],soreness:ctx.pref().memory.metrics?d().soreness:[],goals:ctx.pref().memory.goals?d().goals:[]};const answer=muscleAnswer(normalized,permitted,dayKey());ctx.modal('Caelum / muscle capability',`<div class="caelum-reply">${e(answer||'Open Muscle Map to choose a region and see its exercise-specific evidence.')}</div><button data-action="muscleMap">Open Muscle Map</button>`);return true}
 return {entry,page,handleAction,command};
}
